        pname = rec['values']['ProductName']
        products.append(pname)
        try:
            value[pname] = int(rec['values']['Value'])
            weight[pname] = int(rec['values']['Weight'])
        except Exception as e:
            raise ValueError(f'Invalid numeric data for product {pname}: {e}')
    elif rec['source'].endswith('capacity.csv'):
        try:
            capacity = int(rec['values']['Capacity'])
        except Exception as e:
            raise ValueError(f'Invalid capacity value: {e}')
